 89 |   // mojom::TestService:
 90 |   void DoSomething(DoSomethingCallback callback) override {
 91 |     // Instead of responding normally, unbind the pipe, write some garbage,
 92 |     // and go away.
 93 |     const std::string kBadMessage = "This is definitely not a valid response!";
 94 |     mojo::ScopedMessagePipeHandle pipe = receiver_.Unbind().PassPipe();
 95 |     MojoResult rv = mojo::WriteMessageRaw(
 96 |         pipe.get(), kBadMessage.data(), kBadMessage.size(), nullptr, 0,
 97 |         MOJO_WRITE_MESSAGE_FLAG_NONE);
